import networkx as nx
import random

fixed_edges = {(0,9),(1,10),(2,9)}

def find_graph():
    for attempt in range(10000):
        G = nx.random_regular_graph(3, 12)
        # ensure simple (it should be)
        # check fixed edges present
        ok = True
        for u,v in fixed_edges:
            if not G.has_edge(u,v):
                ok = False
                break
        if ok:
            return G
    return None

G = find_graph()
print(G)
if G:
    print(sorted(G.edges()))
